-- 89 Archer's Range: an archer shoots the targets coming by without
-- breaking stride. The legs are the base clip (walk, or idle when
-- stopped); the "upper" layer, masked at the torso, draws and looses over
-- them (Animation.play_layer, one-shots: the draw holds at full draw, the
-- loose fades back into the walk's arm swing); "breath" is an additive layer
-- on the torso, stronger when standing. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/89-archers-range.scene"
local HIP_X = -300.0
local GROUND = -250.0
local TARGET_BASE = -212.0
local SPACING = 640
local SPEED = 110
local DRAW_AT, LOOSE_AT = 560, 360

local captions = true
local e = {}
local targets = {}
local walking = true
local speed = SPEED
local scroll = 0
local drawn = nil      -- the target being drawn on
local flight = nil
local hits = 0
local shoot_at = nil
local nock_t = 0

local function draw()
    nock_t = 0
    Animation.play_layer(e.Archer, "upper", "animations/ar_draw.skelanim", 0.12, false)
end

local function loose(target)
    Animation.play_layer(e.Archer, "upper", "animations/ar_loose.skelanim", 0.04, false)
    local x, y = Transform.get_world_position(e.Nocked)
    Sprite.set_color(e.Nocked, 1, 1, 1, 0)
    flight = { t = 0, x0 = x, y0 = y, target = target }
end

function init(entity)
    for _, n in ipairs({ "Archer", "Nocked", "Flight", "Path", "Meadow", "Score", "Status" }) do
        e[n] = Entity.find_by_name(n)
    end
    for i = 0, 2 do
        targets[i + 1] = { e = Entity.find_by_name("Target" .. i), stuck = Entity.find_by_name("Stuck" .. i),
                           x = 300 + SPACING * i, shot = false }
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end

    -- Stop and walk: the base clip crossfades, the layers keep playing.
    if Input.is_key_just_pressed("Space") then
        walking = not walking
        Animation.crossfade(e.Archer, walking and "animations/ar_walk.skelanim" or "animations/ar_idle.skelanim", 0.35)
        Animation.set_layer_weight(e.Archer, "breath", walking and 0.35 or 1.0, 0.6)
    end
    local want = walking and SPEED or 0
    speed = speed + (want - speed) * math.min(1, dt * 5)
    scroll = scroll + speed * dt
    Transform.set_position(e.Path, -(scroll % 256), GROUND - 80)
    Transform.set_position(e.Meadow, -(scroll * 0.8 % 512), -215)

    -- The targets come by; the nearest one not yet shot is drawn on, then loosed at.
    for _, t in ipairs(targets) do
        t.x = t.x - speed * dt
        if t.x < -760 then
            t.x = t.x + SPACING * #targets
            t.shot = false
            Sprite.set_color(t.stuck, 1, 1, 1, 0)
        end
        Transform.set_position(t.e, t.x, TARGET_BASE)
        local ahead = t.x - HIP_X
        if walking and not t.shot and drawn == nil and ahead < DRAW_AT and ahead > LOOSE_AT then
            drawn = t
            draw()
            shoot_at = nil
        end
    end
    if Input.is_key_just_pressed("F") and not walking and drawn == nil and flight == nil then
        for _, t in ipairs(targets) do
            if not t.shot and t.x > HIP_X + 150 and t.x < 700 then
                drawn = t
                draw()
                shoot_at = 0.75
                break
            end
        end
    end
    if drawn then
        -- Once the bow is up the arrow shows on the string.
        nock_t = nock_t + dt
        Sprite.set_color(e.Nocked, 1, 1, 1, nock_t > 0.35 and 1 or 0)
        local ready
        if shoot_at then
            shoot_at = shoot_at - dt
            ready = shoot_at <= 0
        else
            ready = drawn.x - HIP_X < LOOSE_AT
        end
        if ready then
            loose(drawn)
            drawn.shot = true
            drawn = nil
        end
    end

    -- The arrow flies to where the target's face will be.
    if flight then
        flight.t = flight.t + dt
        local k = math.min(1, flight.t / 0.4)
        local tx, ty = flight.target.x - 34, TARGET_BASE + 118
        local x = flight.x0 + (tx - flight.x0) * k
        local y = flight.y0 + (ty - flight.y0) * k + math.sin(k * math.pi) * 40
        Transform.set_position(e.Flight, x, y)
        Transform.set_rotation(e.Flight, math.cos(k * math.pi) * 0.25)
        if k >= 1 then
            Transform.set_position(e.Flight, 0, -2000)
            Sprite.set_color(flight.target.stuck, 1, 1, 1, 1)
            hits = hits + 1
            Text.set(e.Score, hits .. (hits == 1 and " hit" or " hits"))
            flight = nil
        end
    end

    UI.set_text(e.Status, walking and "walking - the bow is a layer over the stride" or "standing - F to shoot, Space to walk on")
end
